extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	check("preset_exists", FileAccess.file_exists("res://export_presets.cfg"), "Il file res://export_presets.cfg deve esistere")
	var f := FileAccess.open("res://export_presets.cfg", FileAccess.READ)
	if check("open_preset", f != null, "Impossibile leggere export_presets.cfg"):
		var content := f.get_as_text()
		check("has_filter", content.contains("*.json"), "export_presets.cfg deve contenere il filtro *.json per i file non-risorsa")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var loader_script: GDScript = load("res://story_loader.gd")
	if check("loader_exists", loader_script != null, "Lo script story_loader.gd deve essere valido"):
		var loader = loader_script.new()
		if check("loader_method", has_function(loader, "load_first_chapter"), "story_loader.gd deve contenere load_first_chapter()"):
			var chapter: Dictionary = call_if_exists(loader, "load_first_chapter", [], {})
			check("chapter_loaded", not chapter.is_empty(), "load_first_chapter() deve caricare correttamente il capitolo JSON")

	var save_script: GDScript = load("res://save_system.gd")
	if check("save_exists", save_script != null, "Lo script save_system.gd deve essere valido"):
		var saver = save_script.new()
		if check("save_method", has_function(saver, "save_progress"), "save_system.gd deve contenere save_progress()"):
			var ok: bool = call_if_exists(saver, "save_progress", [{"chapter": 1}], false)
			check("save_success", ok, "save_progress() deve restituire true salvando in user://")
			check("user_file_exists", FileAccess.file_exists("user://progress.json"), "Il file salvato deve trovarsi in user://progress.json")

